// --------------------------------------------------------
// IMAGE (FINAL PASS)
// --------------------------------------------------------
#define VERTEX_RADIUS 1.5

ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

float getRadius(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

float getGroup(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).a;
}

float periodicDist(vec2 a, vec2 b) {
    vec2 d = a - b;
    d = mod(d + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
    return length(d);
}

ivec4 getClosest4(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

int getNearestID(ivec2 c) {
    ivec4 four = getClosest4(c);
    float bestVal = 1e20;
    int   bestID  = -1;
    vec2  fc      = vec2(c);

    for(int i=0; i<4; i++) {
        int candidateID = four[i];
        if(candidateID < 0) continue;

        vec2 center = getParticle(candidateID).xy;
        float rad   = getRadius(candidateID);
        float dist  = periodicDist(fc, center);
        float val   = dist - rad;

        if(val < bestVal) {
            bestVal = val;
            bestID  = candidateID;
        }
    }
    return bestID;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 pc  = ivec2(fragCoord);
    int   sid = getNearestID(pc);

    if(sid < 0) {
        fragColor = vec4(0.0);
        return;
    }

    // Get group color
    vec3 groupColor;
    switch(int(getGroup(sid))) {
        case 0: groupColor = vec3(0.216,1.000,0.000); break; // Green
        case 1: groupColor = vec3(0.059,0.467,1.000); break; // Blue
        case 2: groupColor = vec3(0.843,0.059,1.000); break; // Pink
        default: groupColor = vec3(1.0);
    }

    // Draw particle
    vec2 sitePos = getParticle(sid).xy;
    float distToSite = periodicDist(fragCoord, sitePos);
    float siteRad = getRadius(sid);

    if(distToSite < siteRad) {
        fragColor = vec4(groupColor, 1.0);
    } else {
        fragColor = vec4(0.1, 0.1, 0.1, 1.0); // Dark background
    }
}

// --------------------------------------------------------
// COMMON TAB
// --------------------------------------------------------
#define TOTAL_PARTICLES 5500

// Group percentages (must sum to ~1.0)
#define GROUP1_PERCENT 0.15   // Green
#define GROUP2_PERCENT 0.05   // Blue
#define GROUP3_PERCENT 0.80   // Magenta

// Group size ran&ges
#define G1_RMIN  5.0
#define G1_RMAX  3.0

#define G2_RMIN  7.0
#define G2_RMAX  9.0

#define G3_RMIN  3.0
#define G3_RMAX  4.0

// Toggles
#define START_ALL_FROM_MIN true
#define ALL_IN_SYNC true
#define BASE_WIDTH  1280.0
#define BASE_HEIGHT 720.0

const int PARTICLES = TOTAL_PARTICLES;
const float SPEED = 0.220;
const float FLUCT_SPEED = 7.0;

float hash(int k) {
    uint n = uint(k);
    n = (n << 13U) ^ n;
    n = n * (n * n * 15731U + 789221U) + 1376312589U;
    return uintBitsToFloat((n >> 9U) | 0x3f800000U) - 1.0;
}

// --------------------------------------------------------
// BUFFER A
// --------------------------------------------------------
#define NEAR_DIST  0.0
#define FAR_DIST   120.0

ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec2 periodicDelta(vec2 delta) {
    return mod(delta + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

float getRadius(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

float getPhase(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).g;
}

float getFreq(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).b;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 pix = ivec2(fragCoord);
    int id = pix.x + pix.y * int(iResolution.x);

    if(id >= PARTICLES) {
        fragColor = texelFetch(iChannel0, pix, 0);
        return;
    }

    vec4 prev = texelFetch(iChannel0, pix, 0);
    vec2 pos = prev.xy;
    vec2 vel = prev.zw;

    if(iFrame == 0) {
        float h1 = hash(id);
        float h2 = hash(id + 99999);
        pos = vec2(h1, h2) * iResolution.xy;
        vel = vec2(0.0);
    }

    vec2 force = vec2(0.0);
    force -= vel * 0.3;

    if(iMouse.z > 0.0) {
        vec2 delta = pos - iMouse.xy;
        float dist = length(delta) + 1e-3;
        force += (delta / (dist * dist)) * 10.0;
    }

    float radA = getRadius(id);
    float t = iTime * FLUCT_SPEED;
    float ph = getPhase(id);
    float fr = getFreq(id);
    bool isContracting = (cos(t * fr + ph) < 0.0);

    ivec2 ipos = ivec2(floor(pos));
    ivec4 closeIDs = ivec4(texelFetch(iChannel1, ipos, 0));

    for(int i=0; i<4; i++) {
        int cid = closeIDs[i];
        if(cid < 0 || cid == id) continue;

        vec2 otherPos = getParticle(cid).xy;
        float radB = getRadius(cid);

        vec2 delta = periodicDelta(pos - otherPos);
        float dist = length(delta) + 1e-6;
        vec2 dir = delta / dist;
        float edgeDist = dist - (radA + radB);

        float repulsionFactor = 5.0 / (dist * dist * dist);
        float overlap = (radA + radB) - dist;
        float overlapExtra = (overlap > 0.0) ? 5.0 * overlap : 0.0;

        if(isContracting) {
            float regionFactor = 15.0 - smoothstep(NEAR_DIST, FAR_DIST, edgeDist);

            if(regionFactor > 0.0) {
                force -= dir * (5.0 * regionFactor);
                repulsionFactor *= 0.2;
                overlapExtra *= 4.2;
            }
        }

        force += delta * repulsionFactor;
        if(overlap > 0.0) force += dir * overlapExtra;
    }

    vel += force;
    if(length(vel) > SPEED) vel = normalize(vel) * SPEED;
    pos = mod(pos + vel, iResolution.xy);

    fragColor = vec4(pos, vel);
}

// --------------------------------------------------------
// BUFFER B (Same as original, with pixel–center fix)
// --------------------------------------------------------

ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

float measureParticle(int id, vec2 fragCoord) {
    if (id < 0) return 1e20;
    vec4 dat  = getParticle(id);
    vec2 p    = dat.xy;
    float rad = texelFetch(iChannel3, locFromID(id), 0).r;
    vec2 d = p - fragCoord;
    d = mod(d + 0.5 * iResolution.xy, iResolution.xy) - 0.5 * iResolution.xy;
    return length(d) - rad;
}

void insertion_sort(inout ivec4 i, inout vec4 d, int newID, float newVal) {
    for (int idx = 0; idx < 4; idx++) {
        if (i[idx] == newID) {
            if (newVal < d[idx]) {
                d[idx] = newVal;
                for (int k = idx; k > 0 && d[k] < d[k-1]; k--) {
                    int tmpI = i[k];
                    i[k]     = i[k-1];
                    i[k-1]   = tmpI;
                    float tmpD = d[k];
                    d[k]       = d[k-1];
                    d[k-1]     = tmpD;
                }
            }
            return;
        }
    }
    if (newVal < d[0]) {
        i = ivec4(newID, i[0], i[1], i[2]);
        d = vec4(newVal, d[0], d[1], d[2]);
    } else if (newVal < d[1]) {
        i = ivec4(i[0], newID, i[1], i[2]);
        d = vec4(d[0], newVal, d[1], d[2]);
    } else if (newVal < d[2]) {
        i = ivec4(i[0], i[1], newID, i[2]);
        d = vec4(d[0], d[1], newVal, d[2]);
    } else if (newVal < d[3]) {
        i = ivec4(i[0], i[1], i[2], newID);
        d = vec4(d[0], d[1], d[2], newVal);
    }
}

ivec4 getClosestPrev(ivec2 c) {
    return ivec4(texelFetch(iChannel1, c, 0));
}

ivec2 wrapCoords(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    return ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Convert fragCoord to integer pixel coordinates.
    ivec2 c = ivec2(fragCoord);
    ivec4 newIDs  = ivec4(-1);
    vec4  newVals = vec4(1e20);

    // Use pixel–center coordinates: vec2(c) + 0.5
    for (int dy = -1; dy <= 1; dy++) {
        for (int dx = -1; dx <= 1; dx++) {
            ivec2 cc = wrapCoords(c + ivec2(dx, dy));
            ivec4 four = getClosestPrev(cc);
            for (int i = 0; i < 4; i++) {
                int cand = four[i];
                float val = measureParticle(cand, vec2(c) + 0.5);
                insertion_sort(newIDs, newVals, cand, val);
            }
        }
    }

    float h = hash(c.x + c.y * int(iResolution.x) + iFrame * int(iResolution.x * iResolution.y));
    int rID = int(h * float(PARTICLES));
    float rVal = measureParticle(rID, vec2(c) + 0.5);
    insertion_sort(newIDs, newVals, rID, rVal);

    fragColor = vec4(newIDs);
}

// --------------------------------------------------------
// BUFFER C (Same as original)
// --------------------------------------------------------
ivec2 locFromID(int id) {
    int w = int(iResolution.x);
    return ivec2(id % w, id / w);
}

vec4 getParticle(int id) {
    return texelFetch(iChannel0, locFromID(id), 0);
}

float getRadius(int id) {
    return texelFetch(iChannel3, locFromID(id), 0).r;
}

vec2 periodicDelta(vec2 v) {
    return mod(v + 0.5*iResolution.xy, iResolution.xy) - 0.5*iResolution.xy;
}

ivec4 getClosest4(ivec2 c) {
    ivec2 res = ivec2(iResolution.xy);
    c = ivec2((c.x + res.x) % res.x, (c.y + res.y) % res.y);
    return ivec4(texelFetch(iChannel1, c, 0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 coord = ivec2(fragCoord);
    int   id    = coord.x + coord.y*int(iResolution.x);

    if(id >= PARTICLES) {
        fragColor = vec4(0.0);
        return;
    }

    vec2  posA = getParticle(id).xy;
    float radA = getRadius(id);
    float bestDist = 1e20;

    ivec2 base = ivec2(floor(posA));
    for(int dy=-1; dy<=1; dy++){
        for(int dx=-1; dx<=1; dx++){
            ivec2 sampleCoords = base + ivec2(dx, dy);
            ivec4 nb = getClosest4(sampleCoords);
            for(int i=0; i<4; i++){
                int nid = nb[i];
                if(nid < 0 || nid == id) continue;

                vec2  posB  = getParticle(nid).xy;
                float radB  = getRadius(nid);
                vec2  delta = periodicDelta(posA - posB);
                float effDist = length(delta) - (radA + radB);

                if(effDist < bestDist) bestDist = effDist;
            }
        }
    }

    fragColor = vec4(bestDist, 0.0, 0.0, 1.0);
}

// --------------------------------------------------------
// BUFFER D
// --------------------------------------------------------
int getGroupFromID(int id) {
    int groupBoundary1 = int(float(PARTICLES) * GROUP1_PERCENT); 
    int groupBoundary2 = groupBoundary1 + int(float(PARTICLES) * GROUP2_PERCENT);
    return (id < groupBoundary1) ? 0 : (id < groupBoundary2) ? 1 : 2;
}

void getGroupRanges(int group, out float rmin, out float rmax) {
    if(group == 0) { rmin = G1_RMIN; rmax = G1_RMAX; }
    else if(group == 1) { rmin = G2_RMIN; rmax = G2_RMAX; }
    else { rmin = G3_RMIN; rmax = G3_RMAX; }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    ivec2 c  = ivec2(fragCoord);
    int   id = c.x + c.y * int(iResolution.x);

    if (id >= PARTICLES) {
        fragColor = vec4(0.0);
        return;
    }

    vec4 old = texelFetch(iChannel0, c, 0);

    if(iFrame == 0) {
        int group = getGroupFromID(id);
        float rmin, rmax;
        getGroupRanges(group, rmin, rmax);

        float baseArea = BASE_WIDTH * BASE_HEIGHT;
        float curArea = iResolution.x * iResolution.y;
        float scale = sqrt(curArea / baseArea);

        float initRad = START_ALL_FROM_MIN ? rmin * scale : mix(rmin, rmax, hash(id + 5555)) * scale;
        float phase = ALL_IN_SYNC ? 0.0 : 6.2831853 * hash(id + 12345);
        float freq = ALL_IN_SYNC ? 1.0 : mix(0.2, 1.0, hash(id + 98765));

        fragColor = vec4(initRad, phase, freq, float(group));
    }
    else {
        int group = int(old.a);
        float rmin, rmax;
        getGroupRanges(group, rmin, rmax);

        float rad = ALL_IN_SYNC 
            ? mix(rmin, rmax, 0.5 + 0.5*sin(iTime * FLUCT_SPEED))
            : mix(rmin, rmax, 0.5 + 0.5*sin(iTime * FLUCT_SPEED * old.b + old.g));

        fragColor = vec4(rad, old.g, old.b, old.a);
    }
}
